[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Customers must not take a cart into a single-file shelf aisle, using aisle width and shelf adjacency rather than fixed coordinates so the rule transfers when shelves move or rotate.",
    "abstraction": {
      "state_properties": {
        "one_cell_width": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "between_opposing_shelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                "one_cell_width",
                "between_opposing_shelves"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
