  {
    "id": "park_cart_only_in_open_staging_area",
    "text": "Customers may set down a cart only in an open staging area away from shelves and bottlenecks, so the rule follows navigable clearance rather than the observed parking coordinates.",
    "abstraction": {
      "state_properties": {
        "open_staging_area": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
